// Generates src/openai-tools/_manifests.generated.ts by reading the canonical
// OpenAI tool manifests from @sogni-ai/sogni-protocol and emitting them as
// inline TypeScript constants. This avoids ESM JSON-import attribute
// requirements (Node ≥ 22 rejects bare `import x from './foo.json'` without
// `with { type: 'json' }`, which TypeScript cannot emit conditionally for
// dual CJS+ESM builds).
//
// The generated file is .gitignored. Run via `npm run codegen` or as part of
// `npm run build` / `npm install` (via `prepare`).
import { readFile, writeFile } from 'node:fs/promises';
import { createRequire } from 'node:module';
import { dirname, join } from 'node:path';

const require = createRequire(import.meta.url);
const protocolPkg = require.resolve('@sogni-ai/sogni-protocol/package.json');
const protocolManifestsDir = join(dirname(protocolPkg), 'manifests');

const outFile = join(process.cwd(), 'src', 'openai-tools', '_manifests.generated.ts');

const manifestFiles = ['app-tools.json', 'composition-tools.json', 'generation-tools.json'];

const constNameFor = (filename) => {
  const base = filename.replace(/\.json$/, '');
  // generation-tools → generationToolsManifest
  return `${base.replace(/[-_](.)/g, (_, ch) => ch.toUpperCase())}Manifest`;
};

const sections = [];
for (const file of manifestFiles) {
  const raw = await readFile(join(protocolManifestsDir, file), 'utf8');
  const manifest = JSON.parse(raw);
  if (file === 'generation-tools.json') {
    for (const toolName of ['generate_video', 'animate_photo', 'sound_to_video']) {
      const tool = manifest.tools?.find((candidate) => candidate?.function?.name === toolName);
      const model = tool?.function?.parameters?.properties?.videoModel;
      if (!model) continue;
      model.enum = [...new Set([
        ...(Array.isArray(model.enum) ? model.enum : []),
        'wan3.0-spicy-video',
      ])];
    }
    // FastH3 Reference (minimax-h3-fastvideo-omni-int8_r2v_turbo) gives the
    // FastH3 tier a reference-to-video selector. Until the pinned protocol
    // carries it, add its selectors after the Ref2VA two-stage ones (the order
    // src/tools/definitions/generate-video/definition.ts uses) and drop the
    // protocol's "FastH3 has no R2V mode" lines. A no-op once the protocol has them.
    const fastH3ReferenceSelectors = ['minimax-h3-fasth3-r2v-turbo', 'minimax-h3-fasth3-r2v-turbo-2stage'];
    const generateVideo = manifest.tools?.find((candidate) => candidate?.function?.name === 'generate_video');
    const generateVideoModel = generateVideo?.function?.parameters?.properties?.videoModel;
    if (Array.isArray(generateVideoModel?.enum) && !generateVideoModel.enum.includes(fastH3ReferenceSelectors[0])) {
      const after = generateVideoModel.enum.indexOf('minimax-h3-r2v-balanced-2stage');
      generateVideoModel.enum.splice(after === -1 ? generateVideoModel.enum.length : after + 1, 0, ...fastH3ReferenceSelectors);
    }
    if (typeof generateVideoModel?.description === 'string') {
      generateVideoModel.description = generateVideoModel.description.replace(
        'FastH3 has no R2V mode. ',
        '"minimax-h3-fasth3-r2v-turbo" is FastH3 Reference, the FastH3 tier\'s reference-to-video engine, with the same references, durations, catalog LoRAs and Personal LoRAs as the other R2V selectors; "minimax-h3-fasth3-r2v-turbo-2stage" is its two-stage form and reads targetResolution like the other two-stage selectors. ',
      );
    }
    const animatePhoto = manifest.tools?.find((candidate) => candidate?.function?.name === 'animate_photo');
    const animatePhotoModel = animatePhoto?.function?.parameters?.properties?.videoModel;
    if (typeof animatePhotoModel?.description === 'string') {
      animatePhotoModel.description = animatePhotoModel.description.replace(
        'FastH3 has no R2V mode; use frameRole',
        'FastH3 Reference-to-Video is on generate_video; use frameRole',
      );
    }
  }
  sections.push(`export const ${constNameFor(file)}: unknown = ${JSON.stringify(manifest, null, 2)};`);
}

const banner = `// AUTO-GENERATED by scripts/generate-openai-tools-manifests.mjs.
// Do not edit by hand. Re-run \`npm run codegen\` after changing the source
// JSON in @sogni-ai/sogni-protocol.
/* eslint-disable */
`;

await writeFile(outFile, `${banner}\n${sections.join('\n\n')}\n`, 'utf8');

console.log(`[generate-openai-tools-manifests] wrote ${outFile} from @sogni-ai/sogni-protocol (${manifestFiles.length} manifests)`);
